#!/bin/bash
# merge-verify.sh <candidate-bin-dir> [label]  — one gpuq job: proofs + benches for a merged build vs prism-pascal-best. ~18 min.
C=$1; L=${2:-cand}; R=/home/<user>/CORE/llama/prism-pascal-best/bin; T=/home/<user>/longshot/tune; D=/home/<user>/models-local
M=$D/model-eng-dl/model-eng-Bonsai2-27B-Condensed-mtp-v2-thinkclose.gguf; [ -s $M ] || M=$D/Bonsai2-27B-PTQ1_0-Condensed-P2TG-mtp-v2.gguf
echo "== $L: $C vs ref $R | model $(basename $M)"
echo "== op tests"; LD_LIBRARY_PATH=$C $C/test-backend-ops test -o MUL_MAT -b CUDA0 -p type_a=ptq1_0 2>&1 | grep -E "tests passed|FAIL" | tail -2; LD_LIBRARY_PATH=$C $C/test-backend-ops test -o FLASH_ATTN_EXT -b CUDA0 2>&1 | grep -E "tests passed|FAIL" | tail -1
echo "== llama-bench tg64 at depth (q4_0 KV, ub 256), interleaved"; for b in $C; do LD_LIBRARY_PATH=$b $b/llama-bench -m $M -ngl 99 -fa 1 -ctk q8_0 -ctv q4_0 -ub 256 -p 512 -n 64 -d 0,16384,32768 -r 1 -o md 2>/dev/null | grep -E "pp512|tg64" | sed "s#^#$( [ $b = $R ] && echo REF || echo CAND ) #" | awk -F'|' '{print $1, $(NF-2), $(NF-1)}'; done
echo "== KLD cand vs ref logits (ub=1, 4x512 code tokens)"; [ -s $T/kld_merge_ref.bin ] && true || LD_LIBRARY_PATH=$R $R/llama-perplexity -m $M -ngl 999 -fa on -c 512 -b 512 -ub 1 --chunks 2 -f $T/corpus.txt -ctk q8_0 -ctv q4_0 --kl-divergence-base $T/kld_merge_ref.bin >/dev/null 2>&1; LD_LIBRARY_PATH=$C $C/llama-perplexity -m $M -ngl 999 -fa on -c 512 -b 512 -ub 1 --chunks 2 -f $T/corpus.txt -ctk q8_0 -ctv q4_0 --kl-divergence-base $T/kld_merge_ref.bin --kl-divergence 2>&1 | grep -E "Mean +KLD|Maximum KLD|Same top p" | head -3
srv(){ pkill -f "llama-server.*--port 8112" 2>/dev/null; sleep 1; LD_LIBRARY_PATH=$1 nohup $1/llama-server -m $M --host 127.0.0.1 --port 8112 -ngl 999 -c 49152 -np 1 -b 512 -ub 256 -fa on --jinja -ctk q8_0 -ctv q4_0 --spec-type ngram-mod,draft-mtp --spec-draft-n-max 3 --spec-draft-n-min 0 --spec-draft-p-min 0.75 --reasoning on --reasoning-effort medium --reasoning-budget 4000 --cache-reuse 256 > $T/merge-srv.log 2>&1 </dev/null & for i in $(seq 1 150); do curl -s -m2 http://127.0.0.1:8112/health 2>/dev/null | grep -q ok && return 0; sleep 1; done; return 1; }
gen(){ curl -s -m 900 http://127.0.0.1:8112/v1/chat/completions -H 'Content-Type: application/json' --data @$1 | python3 $T/parse_timings.py; }
python3 -c "import json; print(json.dumps({'messages':[{'role':'user','content':'Write a complete, idiomatic Python module implementing an LRU cache class with get/put, TTL expiry, thread safety, type hints, docstrings and a small pytest suite. Output only code.'}],'max_tokens':600,'temperature':0,'chat_template_kwargs':{'enable_thinking':False}}))" > $T/mv-short.json
python3 - $T <<'PY'
import json,sys; T=sys.argv[1]; txt=(open(f"{T}/corpus.txt").read()*3)[:120000]
json.dump({"messages":[{"role":"user","content":txt+"\n\nAdd a one-line docstring to the first three functions you see above and output only the modified code of those functions."}],"max_tokens":400,"temperature":0,"chat_template_kwargs":{"enable_thinking":False}},open(f"{T}/mv-long.json","w"))
PY
for b in $C; do lab=$( [ $b = $R ] && echo REF || echo CAND ); srv $b || { echo "$lab server failed"; continue; }; gen $T/mv-short.json >/dev/null; echo "$lab serving short: $(gen $T/mv-short.json)"; echo "$lab serving ~30k-token edit turn: $(gen $T/mv-long.json)"; done
echo "== temp-0 text diff (short)"; for b in $C; do srv $b >/dev/null && curl -s -m 600 http://127.0.0.1:8112/v1/chat/completions -H 'Content-Type: application/json' --data @$T/mv-short.json | python3 -c 'import json,sys; print(json.load(sys.stdin)["choices"][0]["message"]["content"])' > $T/mv-text-$( [ $b = $R ] && echo ref || echo cand ).txt; done; cmp -s $T/mv-text-ref.txt $T/mv-text-cand.txt && echo "IDENTICAL" || echo "differs at byte $(cmp $T/mv-text-ref.txt $T/mv-text-cand.txt | grep -oE '[0-9]+' | head -1) of $(wc -c < $T/mv-text-ref.txt)"
pkill -f "llama-server.*--port 8112"; echo "MERGE VERIFY (cand-only) DONE"
